def minimum_nonoverlapping_interval_groups(intervals):
    import heapq
    endings=[]
    for left,right in sorted(intervals):
        if endings and endings[0]<left:heapq.heapreplace(endings,right)
        else:heapq.heappush(endings,right)
    return len(endings)

